"use strict";(self.webpackChunk_=self.webpackChunk_||[]).push([["9111"],{5634(e,t,i){i.r(t),i.d(t,{metadata:()=>n,default:()=>c,frontMatter:()=>s,contentTitle:()=>o,toc:()=>h,assets:()=>l});var n=JSON.parse('{"id":"patterns/qa-pipelines","title":"QA pipelines","description":"Draft, review, revise loops; parallel reviewers with non-overlapping lenses; and the human gate that stops reviewers from over-flagging.","source":"@site/docs/patterns/qa-pipelines.md","sourceDirName":"patterns","slug":"/patterns/qa-pipelines","permalink":"/aible/docs/patterns/qa-pipelines","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":5,"frontMatter":{"sidebar_position":5,"sidebar_label":"5. QA pipelines","title":"QA pipelines","description":"Draft, review, revise loops; parallel reviewers with non-overlapping lenses; and the human gate that stops reviewers from over-flagging."},"sidebar":"mainSidebar","previous":{"title":"4. LLM-as-judge","permalink":"/aible/docs/patterns/llm-as-judge"},"next":{"title":"6. Cost-aware model routing","permalink":"/aible/docs/patterns/cost-aware-model-routing"}}'),r=i(4848),a=i(8453);let s={sidebar_position:5,sidebar_label:"5. QA pipelines",title:"QA pipelines",description:"Draft, review, revise loops; parallel reviewers with non-overlapping lenses; and the human gate that stops reviewers from over-flagging."},o="QA pipelines",l={},h=[{value:"The problem in one diagram",id:"the-problem-in-one-diagram",level:2},{value:"The pattern",id:"the-pattern",level:2},{value:"Decision rules",id:"decision-rules",level:2},{value:"Use a multi-reviewer pipeline when",id:"use-a-multi-reviewer-pipeline-when",level:3},{value:"Do not use a multi-reviewer pipeline when",id:"do-not-use-a-multi-reviewer-pipeline-when",level:3},{value:"The test",id:"the-test",level:3},{value:"Failure modes",id:"failure-modes",level:2},{value:"Reviewer over-flagging",id:"reviewer-over-flagging",level:3},{value:"Deferred items disappearing",id:"deferred-items-disappearing",level:3},{value:"Reviewers with no memory reviewing the same thing twice",id:"reviewers-with-no-memory-reviewing-the-same-thing-twice",level:3},{value:"Lenses that quietly converge",id:"lenses-that-quietly-converge",level:3},{value:"Where it shows up in the teardowns",id:"where-it-shows-up-in-the-teardowns",level:2},{value:"Reference material",id:"reference-material",level:2}];function d(e){let t={a:"a",admonition:"admonition",h1:"h1",h2:"h2",h3:"h3",header:"header",li:"li",mermaid:"mermaid",p:"p",strong:"strong",ul:"ul",...(0,a.R)(),...e.components};return(0,r.jsxs)(r.Fragment,{children:[(0,r.jsx)(t.header,{children:(0,r.jsx)(t.h1,{id:"qa-pipelines",children:"QA pipelines"})}),"\n",(0,r.jsx)(t.p,{children:"I ran a version of this pattern twice while writing this book. Once, months ago, to review the forty-five reference pages this site is built on: three parallel reviewers, one lens each, six phases. And again today, on the two chapters you're reading right now: a pedagogy reviewer and a presentation reviewer, run in parallel, both reporting back inside the same ten minutes. Both times the hard part wasn't getting the reviewers to find things. It was deciding what to do with what they found."}),"\n",(0,r.jsx)(t.p,{children:"A single reviewer, however good, has blind spots that correlate with what it's paying attention to. A reviewer optimizing for correctness won't notice the surrounding explanation is opaque to a newcomer. A reviewer optimizing for clarity might rewrite a passage into something readable that's quietly wrong. A QA pipeline is the fix: several reviewers with genuinely non-overlapping mandates, running against the same draft, followed by one gate that decides what actually changes."}),"\n",(0,r.jsx)(t.h2,{id:"the-problem-in-one-diagram",children:"The problem in one diagram"}),"\n",(0,r.jsx)(t.mermaid,{value:'---\nconfig:\n  themeVariables:\n    fontSize: 16px\n---\nflowchart TB\n  accTitle: A single reviewer misses what it is not looking for\n  accDescr: A draft goes to one reviewer optimizing for clarity. It comes back clearer, but a factual error the reviewer was not looking for passes through unnoticed, because catching it was never the reviewer\'s job.\n  D["Draft"]:::agent --\x3e R["One reviewer,<br/>optimizing for clarity"]:::agent\n  R --\x3e V["Clearer draft \u2014<br/>and a factual error<br/>that was never checked"]:::fail'}),"\n",(0,r.jsxs)("p",{className:"fig-caption",children:[(0,r.jsx)("strong",{children:"Figure 5.1"})," \u2014 One reviewer catches what its mandate points it at. A clarity pass can make a wrong sentence read better without anyone checking whether it's still wrong."]}),"\n",(0,r.jsx)(t.p,{children:"This isn't a claim that any one reviewer is bad at its job. It's that a reviewer's mandate is also a blind spot, and a single reviewer has exactly one. Ask a model to make a page clearer and it will \u2014 and it has no reason to flag that the clearer sentence changed a security-relevant detail, because nobody asked it to look for that. Stack two or three reviewers with different mandates against the same draft and each one's blind spot is a different one's job."}),"\n",(0,r.jsx)(t.h2,{id:"the-pattern",children:"The pattern"}),"\n",(0,r.jsx)(t.mermaid,{value:'---\nconfig:\n  themeVariables:\n    fontSize: 16px\n---\nflowchart TB\n  accTitle: Parallel reviewers with non-overlapping lenses feeding a human gate\n  accDescr: A draft is reviewed by three agents in parallel, each with a single non-overlapping lens, none seeing the others\' output. Each produces a flagged-item list. A person reconciles the three lists into apply, defer, or reject, and only the applied items become the revision.\n  D["Draft"]:::agent --\x3e L1["Reviewer 1<br/>lens A"]:::agent\n  D --\x3e L2["Reviewer 2<br/>lens B"]:::agent\n  D --\x3e L3["Reviewer 3<br/>lens C"]:::agent\n  L1 --\x3e F[("Flagged items,<br/>three lists")]:::store\n  L2 --\x3e F\n  L3 --\x3e F\n  F --\x3e G{"Human gate:<br/>apply, defer, or reject"}:::human\n  G -- "apply" --\x3e REV["Revision"]:::orch\n  G -. "defer" .-> LOG[("Deferred-item log")]:::store'}),"\n",(0,r.jsxs)("p",{className:"fig-caption",children:[(0,r.jsx)("strong",{children:"Figure 5.2"})," \u2014 Three reviewers, one draft, no reviewer sees the others' output. A person reconciles all three lists before anything changes."]}),"\n",(0,r.jsx)(t.p,{children:"Three things make this a pipeline and not just three separate reviews happening near each other. First, the lenses genuinely don't overlap \u2014 in the review process this book itself went through, that was a technical-accuracy lens, a pedagogical lens, and a security lens, chosen specifically because a factual error, a comprehension gap, and an injection vector \u2014 a hidden instruction planted in the input that tricks the model into doing something it shouldn't \u2014 are different kinds of defect that don't show up to the same reader. Second, the reviewers don't see each other's output \u2014 each one reads the same draft cold, so their disagreements are real signal, not one reviewer anchoring on another's framing. Third, and this is the part that actually makes the pipeline work rather than just make noise: a person reconciles all three lists into three buckets \u2014 apply now, defer, or reject \u2014 instead of applying everything a reviewer suggested."}),"\n",(0,r.jsx)(t.p,{children:'That third part matters more than it sounds like it should. Reviewers, especially the ones optimizing for clarity or completeness, will find an unbounded number of things to improve \u2014 every page can always be a little clearer, every example can always have one more caveat. Applying all of it doesn\'t converge on a better page, it converges on a longer one. The gate isn\'t there to catch reviewer mistakes; the reviewers are usually right about the specific thing they flagged. It\'s there because "right about this one thing" and "worth changing right now" are different questions, and only a person weighing the whole draft can answer the second one.'}),"\n",(0,r.jsx)(t.h2,{id:"decision-rules",children:"Decision rules"}),"\n",(0,r.jsx)(t.h3,{id:"use-a-multi-reviewer-pipeline-when",children:"Use a multi-reviewer pipeline when"}),"\n",(0,r.jsxs)(t.ul,{children:["\n",(0,r.jsx)(t.li,{children:"The kinds of defects you care about genuinely don't overlap \u2014 a factual error and a confusing explanation are different failure modes, and a single reviewer prompted to catch everything usually catches whichever one its prompt leans toward."}),"\n",(0,r.jsx)(t.li,{children:"You can name the lenses in advance. If you can't say what each reviewer is specifically responsible for catching, you don't have separate lenses, you have the same reviewer run three times with different adjectives in its prompt."}),"\n",(0,r.jsx)(t.li,{children:"Someone is going to sit at the gate. A pipeline that auto-applies everything every reviewer flags isn't a QA pipeline, it's a length generator."}),"\n"]}),"\n",(0,r.jsx)(t.h3,{id:"do-not-use-a-multi-reviewer-pipeline-when",children:"Do not use a multi-reviewer pipeline when"}),"\n",(0,r.jsxs)(t.ul,{children:["\n",(0,r.jsx)(t.li,{children:"One good reviewer already catches what you care about. Three lenses for a one-paragraph change is review theater, not quality control."}),"\n",(0,r.jsx)(t.li,{children:"Nobody has time to reconcile the output. Three lists of flagged items that nobody triages is worse than one list, because now the unaddressed backlog is three times as long and looks like it was handled."}),"\n",(0,r.jsx)(t.li,{children:"The draft changes fast enough that review can't keep up. A pipeline built for a document that's revised once a week doesn't fit a system generating new output every request \u2014 that's chapter 4's territory, a sampled judge \u2014 a second AI call that grades only a random slice of the output, not all of it \u2014 not a full review pass."}),"\n"]}),"\n",(0,r.jsx)(t.h3,{id:"the-test",children:"The test"}),"\n",(0,r.jsxs)(t.p,{children:["Ask: ",(0,r.jsx)(t.strong,{children:"can I name, for each reviewer, one category of defect the other reviewers would not have caught?"})," If two of your three reviewers would have flagged the same issue, you don't have three lenses, you have redundancy dressed up as coverage."]}),"\n",(0,r.jsx)(t.h2,{id:"failure-modes",children:"Failure modes"}),"\n",(0,r.jsx)(t.h3,{id:"reviewer-over-flagging",children:"Reviewer over-flagging"}),"\n",(0,r.jsx)(t.p,{children:"Left unconstrained, a reviewer optimizing for any single quality dimension will find an unbounded number of things to improve, because there's always a next improvement. In the review pass this book's reference pages went through, each phase's three reviewers together produced fifteen to thirty-five flagged items for five to seven pages, and something like a third of that was worth deferring or rejecting outright \u2014 not because the reviewers were wrong, but because not every true observation is worth acting on today. Fix: the gate isn't optional, and its job is explicitly to say no to correct feedback, not just incorrect feedback."}),"\n",(0,r.jsx)(t.h3,{id:"deferred-items-disappearing",children:"Deferred items disappearing"}),"\n",(0,r.jsx)(t.p,{children:"A long session runs, review happens, some flagged items get deferred rather than applied \u2014 and if the deferred list only exists in the conversation, it's gone the moment that conversation is compressed \u2014 older turns automatically summarized away to make room \u2014 or ends. This book's own authoring process learned this the hard way: writing deferred items to a durable file at review time, not at phase close, is what survives a session ending early. An applied change is recoverable from a diff \u2014 the record of exactly what changed between two versions of a file; a deferred idea that only lived in chat history is not."}),"\n",(0,r.jsx)(t.h3,{id:"reviewers-with-no-memory-reviewing-the-same-thing-twice",children:"Reviewers with no memory reviewing the same thing twice"}),"\n",(0,r.jsx)(t.p,{children:"Each reviewer agent starts fresh, with no memory of a prior session's review. If you don't tell the new reviewer what was already fixed, it re-flags the same items the last pass already applied, and you spend the gate's attention re-deciding things that were already decided. Fix: brief every reviewer with what's already been addressed, not just the current draft."}),"\n",(0,r.jsx)(t.h3,{id:"lenses-that-quietly-converge",children:"Lenses that quietly converge"}),"\n",(0,r.jsx)(t.p,{children:'Two reviewers with different names but the same underlying instinct \u2014 "check for clarity" and "check for readability" are close enough to be the same lens twice \u2014 produce agreeing lists that look like confirmation but are really just one opinion counted twice. Fix: the test above. If you can\'t name what one lens catches that the other wouldn\'t, merge them.'}),"\n",(0,r.jsx)(t.h2,{id:"where-it-shows-up-in-the-teardowns",children:"Where it shows up in the teardowns"}),"\n",(0,r.jsxs)(t.ul,{children:["\n",(0,r.jsxs)(t.li,{children:[(0,r.jsx)(t.strong,{children:"This site's reference library"})," was built through exactly this pattern, though it isn't one of the teardowns below: three parallel reviewers (technical accuracy, pedagogical, security), each reading the same draft with no visibility into the others' output, reconciled by a human gate across six phases. The chapter you're reading went through a smaller version of the same thing today \u2014 two reviewers, not three, with different lenses (structure and narrative; presentation and rendering), and the same gate."]}),"\n",(0,r.jsxs)(t.li,{children:[(0,r.jsx)(t.strong,{children:(0,r.jsx)(t.a,{href:"../teardowns/lyceum",children:"Lyceum"})})," runs a nine-agent, four-phase QA pipeline over generated course content \u2014 the largest reviewer pipeline in this book's teardowns, and one of the open questions once that teardown is written is whether its phases are genuinely non-overlapping lenses or a longer version of the same check repeated."]}),"\n",(0,r.jsxs)(t.li,{children:[(0,r.jsx)(t.strong,{children:(0,r.jsx)(t.a,{href:"../teardowns/projectos",children:"ProjectOS"})})," doesn't run a multi-reviewer pipeline in this sense \u2014 its quality control is the single sampled judge from chapter 4, which is a different pattern solving a related problem at a different cadence."]}),"\n"]}),"\n",(0,r.jsx)(t.admonition,{title:"My take",type:"tip",children:(0,r.jsx)(t.p,{children:"The thing I didn't expect, running this pattern on my own writing today, is how much the gate is actually the expensive part, not the review. Getting two reviewers to independently find real problems took about ten minutes and no judgment from me at all. Deciding which of their findings to act on, in what order, without either ignoring something true or rewriting half the book on the spot \u2014 that took the rest of the session. If you're budgeting time for a QA pipeline, budget it for the gate, not the reviewers. The reviewers are the cheap part."})}),"\n",(0,r.jsx)(t.h2,{id:"reference-material",children:"Reference material"}),"\n",(0,r.jsxs)(t.ul,{children:["\n",(0,r.jsxs)(t.li,{children:[(0,r.jsx)(t.a,{href:"../meta-infrastructure/red-teaming",children:"Red Teaming"})," \u2014 adversarial review as a fourth kind of lens, distinct from correctness or clarity."]}),"\n",(0,r.jsxs)(t.li,{children:[(0,r.jsx)(t.a,{href:"../meta-infrastructure/evals",children:"Evals"})," \u2014 turning what a reviewer catches into a repeatable check, once you know what you're looking for."]}),"\n",(0,r.jsxs)(t.li,{children:[(0,r.jsx)(t.a,{href:"../core-building-blocks/multi-agent-systems",children:"Multi-Agent Systems"})," \u2014 the critic-revise loop and validator-agent patterns this chapter's parallel-reviewer shape is a variant of."]}),"\n",(0,r.jsxs)(t.li,{children:[(0,r.jsx)(t.a,{href:"../core-building-blocks/structured-outputs",children:"Structured Outputs"})," \u2014 typed flagged-item lists, so a gate can triage programmatically instead of re-reading free text."]}),"\n"]})]})}function c(e={}){let{wrapper:t}={...(0,a.R)(),...e.components};return t?(0,r.jsx)(t,{...e,children:(0,r.jsx)(d,{...e})}):d(e)}},8453(e,t,i){i.d(t,{R:()=>s,x:()=>o});var n=i(6540);let r={},a=n.createContext(r);function s(e){let t=n.useContext(a);return n.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function o(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(r):e.components||r:s(e.components),n.createElement(a.Provider,{value:t},e.children)}}}]);